import React, { useState, useEffect } from 'react';

// This component will display and allow editing of process fields.
// For now, it shows read-only fields with sample data.
const ProcessDetails = ({ processId, processData: initialProcessData, onUpdate }) => {
  // Sample structure, will be fetched or updated by AI later
  const sampleData = {
    general_description: 'This is a sample general description for the process. It outlines the main purpose and goals.',
    process_steps: ['Step 1: Do this first.', 'Step 2: Then do that.', 'Step 3: Finally, do this.'],
    scope: 'This process applies to all new hires in the engineering department.',
    inputs: ['New hire information sheet', 'Signed offer letter'],
    outputs: ['Completed onboarding checklist', 'System access granted'],
    kpis: ['Time to onboard < 5 days', 'Employee satisfaction > 90%'],
    roles_responsibilities: ['Hiring Manager: Oversee onboarding', 'IT Support: Grant system access'],
    exceptions_special_cases: ['If new hire is remote, schedule virtual meet & greet.'],
  };

  const [processData, setProcessData] = useState(initialProcessData || sampleData);
  const [isEditing, setIsEditing] = useState(false); // For future edit functionality

  useEffect(() => {
    // In a real app, fetch process details by processId if not already provided
    // For now, we use sample or passed-in data.
    if (initialProcessData) {
      setProcessData(initialProcessData);
    }
    console.log(`ProcessDetails for ${processId} mounted.`);
  }, [processId, initialProcessData]);

  const handleChange = (field, value, index = null) => {
    // Basic change handler for future editing
    if (Array.isArray(processData[field])) {
      const newList = [...processData[field]];
      newList[index] = value;
      setProcessData(prev => ({ ...prev, [field]: newList }));
    } else {
      setProcessData(prev => ({ ...prev, [field]: value }));
    }
  };

  // Simple display of list items
  const renderList = (items, fieldName) => (
    <ul>
      {items && items.map((item, index) => (
        <li key={`${fieldName}-${index}`}>{item}</li>
      ))}
    </ul>
  );

  const sectionStyle = {
    marginBottom: 'calc(var(--spacing-unit, 16px) * 1.5)',
  };

  const labelStyle = {
    fontWeight: 'bold',
    display: 'block',
    marginBottom: 'calc(var(--spacing-unit, 16px) / 4)',
    color: 'var(--primary-color)'
  };

  const textStyle = {
    fontSize: '0.95em',
    lineHeight: '1.6',
    color: '#333'
  };

  return (
    <div style={{ overflowY: 'auto', maxHeight: '40vh' /* Or adjust as needed */ }}>
      <h4>Extracted Process Details</h4>

      <div style={sectionStyle}>
        <label style={labelStyle}>General Description:</label>
        <p style={textStyle}>{processData.general_description}</p>
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Process Steps:</label>
        {renderList(processData.process_steps, 'steps')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Scope:</label>
        <p style={textStyle}>{processData.scope}</p>
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Inputs:</label>
        {renderList(processData.inputs, 'inputs')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Outputs:</label>
        {renderList(processData.outputs, 'outputs')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>KPIs:</label>
        {renderList(processData.kpis, 'kpis')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Roles & Responsibilities:</label>
        {renderList(processData.roles_responsibilities, 'roles')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Exceptions & Special Cases:</label>
        {renderList(processData.exceptions_special_cases, 'exceptions')}
      </div>

      {/* Add Edit/Save buttons later */}
    </div>
  );
};

export default ProcessDetails;
